 "Anzahl", "group": "Elemente/Raumbuch/Sonstiges", "n": 13, "phaseSeed": ""}, {"key": "AP_Gefaehrdung", "group": "Elemente/Raumbuch/Sonstiges", "n": 1, "phaseSeed": ""}, {"key": "AP_Geistige", "group": "Elemente/Raumbuch/Sonstiges", "n": 1, "phaseSeed": ""}, {"key": "Ar Reinheit", "group": "Elemente/Raumbuch/Sonstiges", "n": 2, "phaseSeed": ""}, {"key": "Bezeichnung", "group": "Elemente/Raumbuch/Sonstiges", "n": 22, "phaseSeed": ""}, {"key": "CO2 Reinheit", "group": "Elemente/Raumbuch/Sonstiges", "n": 2, "phaseSeed": ""}, {"key": "CO2_Melder", "group": "Elemente/Raumbuch/Sonstiges", "n": 3, "phaseSeed": ""}, {"key": "DL ISO 8573", "group": "Elemente/Raumbuch/Sonstiges", "n": 2, "phaseSeed": ""}, {"key": "Einheit", "group": "Elemente/Raumbuch/Sonstiges", "n": 15, "phaseSeed": ""}, {"key": "el_Bez", "group": "Elemente/Raumbuch/Sonstiges", "n": 1, "phaseSeed": ""}, {"key": "ElementID", "group": "Elemente/Raumbuch/Sonstiges", "n": 14, "phaseSeed": ""}, {"key": "Gaswarneinrichtung-Art", "group": "Elemente/Raumbuch/Sonstiges", "n": 1, "phaseSeed": ""}, {"key": "Ge Reinheit", "group": "Elemente/Raumbuch/Sonstiges", "n": 1, "phaseSeed": ""}, {"key": "Gebaeude_Bestand", "group": "Elemente/Raumbuch/Sonstiges", "n": 1, "phaseSeed": ""}, {"key": "Gewerke_Nr", "group": "Elemente/Raumbuch/Sonstiges", "n": 11, "phaseSeed": ""}, {"key": "GHG", "group": "Elemente/Raumbuch/Sonstiges", "n": 11, "phaseSeed": ""}, {"key": "H2 Reinheit", "group": "Elemente/Raumbuch/Sonstiges", "n": 1, "phaseSeed": ""}, {"key": "He Reinheit", "group": "Elemente/Raumbuch/Sonstiges", "n": 1, "phaseSeed": ""}, {"key": "Hersteller", "group": "Elemente/Raumbuch/Sonstiges", "n": 9, "phaseSeed": ""}, {"key": "id", "group": "Elemente/Raumbuch/Sonstiges", "n": 13, "phaseSeed": ""}, {"key": "Inventarnummer", "group": "Elemente/Raumbuch/Sonstiges", "n": 9, "phaseSeed": ""}, {"key": "Kategorie", "group": "Elemente/Raumbuch/Sonstiges", "n": 14, "phaseSeed": ""}, {"key": "Kurzbeschreibung", "group": "Elemente/Raumbuch/Sonstiges", "n": 10, "phaseSeed": ""}, {"key": "LHe", "group": "Elemente/Raumbuch/Sonstiges", "n": 1, "phaseSeed": ""}, {"key": "N2 Reinheit", "group": "Elemente/Raumbuch/Sonstiges", "n": 2, "phaseSeed": ""}, {"key": "N20", "group": "Elemente/Raumbuch/Sonstiges", "n": 1, "phaseSeed": ""}, {"key": "Neu/Bestand", "group": "Elemente/Raumbuch/Sonstiges", "n": 13, "phaseSeed": ""}, {"key": "O2 Reinheit", "group": "Elemente/Raumbuch/Sonstiges", "n": 2, "phaseSeed": ""}, {"key": "O2_Mangel", "group": "Elemente/Raumbuch/Sonstiges", "n": 3, "phaseSeed": ""}, {"key": "PHY_Akustik_Schallgrad", "group": "Elemente/Raumbuch/Sonstiges", "n": 1, "phaseSeed": ""}, {"key": "PHY_Akustik_T500", "group": "Elemente/Raumbuch/Sonstiges", "n": 1, "phaseSeed": ""}, {"key": "Projektname", "group": "Elemente/Raumbuch/Sonstiges", "n": 10, "phaseSeed": ""}, {"key": "Raumhoehe", "group": "Elemente/Raumbuch/Sonstiges", "n": 7, "phaseSeed": ""}, {"key": "Raumhoehe_Soll", "group": "Elemente/Raumbuch/Sonstiges", "n": 2, "phaseSeed": ""}, {"key": "RaumNr_Bestand", "group": "Elemente/Raumbuch/Sonstiges", "n": 1, "phaseSeed": ""}, {"key": "Raumtyp BH", "group": "Elemente/Raumbuch/Sonstiges", "n": 3, "phaseSeed": ""}, {"key": "Seriennummer", "group": "Elemente/Raumbuch/Sonstiges", "n": 9, "phaseSeed": ""}, {"key": "Spezialgase", "group": "Elemente/Raumbuch/Sonstiges", "n": 1, "phaseSeed": ""}, {"key": "Standort", "group": "Elemente/Raumbuch/Sonstiges", "n": 9, "phaseSeed": ""}, {"key": "SummevonAnzahl", "group": "Elemente/Raumbuch/Sonstiges", "n": 1, "phaseSeed": ""}, {"key": "TABELLE_Elemente_idTABELLE_Elemente", "group": "Elemente/Raumbuch/Sonstiges", "n": 9, "phaseSeed": ""}, {"key": "Taetigkeiten", "group": "Elemente/Raumbuch/Sonstiges", "n": 1, "phaseSeed": ""}, {"key": "Timestamp", "group": "Elemente/Raumbuch/Sonstiges", "n": 1, "phaseSeed": ""}, {"key": "Typ", "group": "Elemente/Raumbuch/Sonstiges", "n": 9, "phaseSeed": ""}, {"key": "Variante", "group": "Elemente/Raumbuch/Sonstiges", "n": 14, "phaseSeed": ""}, {"key": "Verwendung", "group": "Elemente/Raumbuch/Sonstiges", "n": 9, "phaseSeed": ""}, {"key": "VEXAT_Zone", "group": "Elemente/Raumbuch/Sonstiges", "n": 1, "phaseSeed": ""}, {"key": "Wert", "group": "Elemente/Raumbuch/Sonstiges", "n": 15, "phaseSeed": ""}, {"key": "´H2 Reinheit", "group": "Elemente/Raumbuch/Sonstiges", "n": 1, "phaseSeed": ""}], "groupsOrder": ["Raumkopf/ID", "Allgemein", "Architektur/Statik", "Elektro", "Haustechnik/HKLS", "Med-Gas/Labor-Gas", "Labor-Wasser", "Anmerkungen", "Raum – sonstige", "Elemente/Raumbuch/Sonstiges"], "groupLabels": {"Raumkopf/ID": "Kopf/ID", "Allgemein": "Allgem.", "Architektur/Statik": "Arch./Statik", "Elektro": "Elektro", "Haustechnik/HKLS": "HKLS", "Med-Gas/Labor-Gas": "MedGas/Gas", "Labor-Wasser": "Lab-H₂O", "Anmerkungen": "Anm.", "Raum – sonstige": "Raum-sonst.", "Elemente/Raumbuch/Sonstiges": "Elem./RB"}};
    const PHASES = ["", "Vorentwurf", "Entwurf", "Einreichung", "Ausschreibung/Tender", "Ausführungsplanung", "Ausführung"];
    const CATLBL = {"bauangaben_neu": "Bauangaben Neu", "bauangaben": "Bauangaben", "einreichung": "Einreichung", "elementReports": "Element-/Raum Berichte", "einbringwege": "Einbringwege", "oldReports": "Historische Berichte"};
    const GROUPS = DATA.groupsOrder, GLBL = DATA.groupLabels;
    const LSKEY = "parameterphasen_v1";

    function loadPhases() {
        let saved = {};
        try { saved = JSON.parse(localStorage.getItem(LSKEY) || "{}"); } catch(e) {}
        DATA.params.forEach(p => { p.cur = (p.key in saved) ? saved[p.key] : (p.phaseSeed || ""); });
    }
    function savePhases() {
        const o = {}; DATA.params.forEach(p => { if (p.cur) o[p.key] = p.cur; });
        try { localStorage.setItem(LSKEY, JSON.stringify(o)); } catch(e) {}
    }
    function phaseSelect(p) {
        const seeded = p.phaseSeed ? ' title="aus Code vorbelegt (isnotVorentwurf)"' : '';
        let s = '<select class="form-select form-select-sm phase-sel"'+seeded+' data-key="'+encodeURIComponent(p.key)+'">';
        PHASES.forEach(ph => { s += '<option value="'+ph+'"'+(ph===p.cur?' selected':'')+'>'+(ph||'—')+'</option>'; });
        return s + '</select>';
    }
    function badge(n) {
        if (!n) return '<span class="text-muted">·</span>';
        let c = n>=15?'text-bg-danger':n>=8?'text-bg-warning':n>=3?'text-bg-info':'text-bg-secondary';
        return '<span class="badge '+c+'">'+n+'</span>';
    }

    $(document).ready(function() {
        loadPhases();
        const reps = DATA.reports;

        // ---------- Parameter & Phase ----------
        const pcols = [{title:'Gruppe'},{title:'Parameter'},{title:'Phase (ab)'},{title:'#Ber.',className:'text-end'}]
            .concat(reps.map(r => ({title:r.text, className:'text-center', orderable:false})));
        const pdata = DATA.params.map(p => {
            const row = [GLBL[p.group]||p.group, p.key, phaseSelect(p), p.n];
            reps.forEach(r => row.push(r.fields.indexOf(p.key)>=0 ? '<span class="text-success fw-bold">✓</span>' : ''));
            return row;
        });
        const tblP = $('#tblParam').DataTable({
            data: pdata, columns: pcols, order:[[0,'asc'],[1,'asc']],
            scrollX:true, scrollY:'62vh', scrollCollapse:true, paging:false,
            fixedColumns:{ start:3 },
            dom:'Bfrtip',
            buttons:[
                {extend:'colvis', className:'btn btn-sm btn-outline-secondary', text:'Berichtsspalten', columns:':gt(3)'},
                {extend:'csvHtml5', className:'btn btn-sm btn-outline-secondary', text:'CSV', title:'Parameter-Phasen'}
            ]
        });
        $('#tblParam').on('change', '.phase-sel', function() {
            const key = decodeURIComponent($(this).data('key'));
            const p = DATA.params.find(x => x.key===key); if (p) p.cur = $(this).val();
            savePhases(); renderPhaseBoard();
        });

        // Filter Gruppe
        const gsel=$('#fltGroup'); GROUPS.forEach(g=>gsel.append('<option value="'+(GLBL[g]||g)+'">'+(GLBL[g]||g)+'</option>'));
        gsel.on('change', function(){ tblP.column(0).search(this.value?'^'+$.fn.dataTable.util.escapeRegex(this.value)+'$':'', true, false).draw(); });
        // Filter Phase (custom, liest aktuellen Select-Wert)
        const phsel=$('#fltPhase'); PHASES.filter(x=>x).forEach(ph=>phsel.append('<option value="'+ph+'">'+ph+'</option>')); phsel.append('<option value="__none__">(ohne Phase)</option>');
        // Filter Bericht
        const rsel=$('#fltReport'); reps.forEach((r,i)=>rsel.append('<option value="'+i+'">'+r.text+'</option>'));
        let repFilter=null, phaseFilter='';
        // eigener kombinierter Filter
        $.fn.dataTable.ext.search.push(function(settings, rowData, dataIndex) {
            if (settings.nTable.id !== 'tblParam') return true;
            const p = DATA.params[dataIndex];
            if (repFilter!==null) { const r=reps[repFilter]; if (r.fields.indexOf(p.key)<0) return false; }
            if (phaseFilter) { const cur=p.cur||''; if (phaseFilter==='__none__') { if (cur!=='') return false; } else if (cur!==phaseFilter) return false; }
            return true;
        });
        rsel.on('change', function(){ repFilter = this.value===''?null:parseInt(this.value,10); tblP.draw(); });
        phsel.on('change', function(){ phaseFilter = this.value; tblP.draw(); });

        // ---------- Gruppen-Matrix ----------
        const gcols=[{title:'Bericht'},{title:'Kategorie'}].concat(GROUPS.map(g=>({title:GLBL[g]||g,className:'text-center'}))).concat([{title:'Σ',className:'text-end'}]);
        const gdata=reps.map(r=>{const row=[r.text,CATLBL[r.category]];GROUPS.forEach(g=>row.push(badge(r.groups[g]||0)));row.push('<strong>'+r.n+'</strong>');return row;});
        $('#tblGruppen').DataTable({data:gdata,columns:gcols,pageLength:40,order:[[1,'asc'],[0,'asc']],dom:'Bfrtip',
            buttons:[{extend:'csvHtml5',className:'btn btn-sm btn-outline-secondary',text:'CSV',title:'Gruppen-Matrix'}]});

        // ---------- Katalog ----------
        const kdata=reps.map(r=>[CATLBL[r.category],r.text,r.url,r.typ,r.n]);
        $('#tblKatalog').DataTable({data:kdata,pageLength:40,order:[[0,'asc'],[1,'asc']],
            columns:[{title:'Kategorie'},{title:'Bericht'},{title:'Script'},{title:'Typ'},{title:'#Felder',className:'text-end'}],
            dom:'Bfrtip',buttons:[
                {extend:'csvHtml5',className:'btn btn-sm btn-outline-secondary',text:'CSV',title:'Berichtskatalog'},
                {extend:'excelHtml5',className:'btn btn-sm btn-outline-secondary',text:'Excel',title:'Berichtskatalog'}]});

        // ---------- Phasen-Übersicht ----------
        renderPhaseBoard();
        $('#btnExport').on('click', function(){
            const o={}; DATA.params.forEach(p=>{ o[p.key]={gruppe:p.group, phase:p.cur||"", berichte:reps.filter(r=>r.fields.indexOf(p.key)>=0).map(r=>r.text)}; });
            const blob=new Blob([JSON.stringify(o,null,2)],{type:'application/json'});
            const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='parameter_phasen.json';a.click();
        });
        $('#btnReset').on('click', function(){ try{localStorage.removeItem(LSKEY);}catch(e){} location.reload(); });
    });

    function renderPhaseBoard() {
        const board=$('#phaseBoard'); board.empty();
        const order=PHASES.slice(1).concat(['(ohne Phase)']);
        const byPhase={}; order.forEach(p=>byPhase[p]=[]);
        DATA.params.forEach(p=>{ const ph=p.cur||'(ohne Phase)'; (byPhase[ph]=byPhase[ph]||[]).push(p); });
        order.forEach(ph=>{
            const list=byPhase[ph]||[];
            // nach Gruppe bündeln
            const byG={}; list.forEach(p=>{(byG[p.group]=byG[p.group]||[]).push(p.key);});
            let body='';
            GROUPS.forEach(g=>{ if(byG[g]) body += '<li class="list-group-item py-1"><span class="badge text-bg-light me-1">'+(GLBL[g]||g)+'</span>'+byG[g].map(k=>'<span class="me-2">'+k+'</span>').join('')+'</li>'; });
            if(!body) body='<li class="list-group-item text-muted py-1">—</li>';
            const head=ph==='(ohne Phase)'?'text-bg-light':'text-bg-primary';
            board.append('<div class="col-12 col-xl-6"><div class="card h-100"><div class="card-header py-1 d-flex justify-content-between '+head+'"><strong>'+ph+'</strong><span class="badge text-bg-secondary">'+list.length+' Param.</span></div><ul class="list-group list-group-flush small">'+body+'</ul></div></div>');
        });
    }
</script>
</body>
</html>